export function findUtilityByFeatureId(featureId: string): {
  workspace: WorkspaceDefinition;
  group: GroupDefinition;
  utility: UtilityDefinition;
  feature: FeatureDefinition;
} | undefined {
  for (const ws of WORKSPACES) {
    for (const group of ws.groups) {
      for (const utility of group.utilities) {
        const feature = utility.features?.find((f) => f.id === featureId);
        if (feature) {
          return { workspace: ws, group, utility, feature };
        }
      }
    }
  }
  return undefined;
}
